    address1, ce1,
    d1, we1, 
    
     
    reset, clk);

parameter DataWidth = 256;
parameter AddressWidth = 9;
parameter AddressRange = 320;
 
input[AddressWidth-1:0] address0;
input ce0;

output reg[DataWidth-1:0] q0; 
 
input[AddressWidth-1:0] address1;
input ce1;
input[DataWidth-1:0] d1;
input we1; 


input reset;
input clk;

(* ram_style = "hls_ultra" , cascade_height = 1 *)reg [DataWidth-1:0] ram[0:AddressRange-1];

initial begin
    $readmemh("D:/file/project/git/light-mamba/SPINAL/src/main/verilog/RMSNORM_QUANT_1/RMSNORM_QUANT_1_do_rmsnorm_rmsnorm_inst_X_BUF_84_RAM_2P_URAM_1R1W.dat", ram);
